  stk segs m lo (bv_unsigned sp) -> lo <= bv_unsigned sp - ASN1_GET_BITSTRING_STACK_A -> alloc_ceiling <= lo ->
  bv_unsigned sp mod 16 = 0 ->
  (PP + 8 <= lo \/ bv_unsigned sp <= PP) ->
  (BSP + 24 <= lo \/ bv_unsigned sp <= BSP) ->
  (Z.of_nat (length bs) = 0 \/ BUF + Z.of_nat (length bs) <= lo \/ bv_unsigned sp <= BUF) ->
